 p_id=>wwv_flow_imp.id(21259960975259817)
,p_event_id=>wwv_flow_imp.id(21259833376259816)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_template       blob;',
'    l_template_id    number;',
'    l_data           sys.json_object_t := sys.json_object_t();',
'    l_document       blob;',
'BEGIN',
'',
'    SELECT file_content',
'      INTO l_template',
'      FROM apex_application_static_files',
'     WHERE file_name = ''templates/customer-order.docx'' and APPLICATION_ID = :APP_ID;',
'',
'    l_template_id := apex_print.upload_template( p_template => l_template );',
'',
'    l_data.put( ''name'', ''Scott'' );',
'',
'    l_document := apex_print.generate_document(',
'                      p_data         => l_data.to_clob,',
'                      p_template_id  => l_template_id );',
'',
'    apex_print.remove_template( p_template_id => l_template_id );',
'apex_http.download(',
'        p_blob          => l_document,',
'        p_content_type  => ''application/pdf'',',
'        p_filename      => ''hello.pdf'' );',
'',
'    apex_application.stop_apex_engine;',
'EXCEPTION',
'    WHEN others THEN',
'        apex_print.remove_template( p_template_id => l_template_id );',
'END;'))
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
