wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(21260605238259824)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'New'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_file      apex_application_static_files%rowtype;',
'    l_file_2    blob;',
'    l_id        number;',
'    l_pdf       blob;',
'    l_json      clob;',
'    l_data      sys.json_object_t := sys.json_object_t();',
'begin',
'',
'    select *',
'      into l_file',
'      from apex_application_static_files',
'     where file_name = ''templates/employees.docx'' and application_id = :APP_ID;',
'/*',
'   l_file_2 := DBMS_CLOUD.GET_OBJECT(',
'     credential_name => ''OCI$RESOURCE_PRINCIPAL'',',
'     object_uri => ''https://natdcshjumpstartprod.objectstorage.us-ashburn-1.oci.customer-oci.com/n/natdcshjumpstartprod/b/doc_gen/o/template%2Femployees.docx''); ',
'*/',
'    l_id := apex_print.upload_template(',
'                p_template => l_file.file_content);',
'',
'    select json_object( ',
'        ''currentDate''   value to_char( sysdate, ''DD MON YYYY'' ),',
'        ''employees''     value',
'            json_arrayagg( ',
'                json_object(''name''      value e.ename,',
'                           ''job''        value e.job,',
'                           ''hiredate''   value to_char( e.hiredate, ''DD MON YYYY''),',
'                           ''salary''     value e.sal,',
'                           ''commission'' value nvl(e.comm,0),',
'                           ''department'' value d.dname,',
'                           ''location''   value d.loc,',
'                           ''manager''    value nvl(m.ename,''-'') ) pretty ) returning clob) into l_json',
'  from eba_demo_dg_emp e',
'  join eba_demo_dg_dept d',
'    on e.deptno = d.deptno',
'  left join eba_demo_dg_emp m',
'    on e.mgr = m.empno;',
'    l_data := JSON_OBJECT_T.PARSE(l_json);',
'    ',
'    l_pdf := apex_print.generate_document(',
'            p_data          => l_data.to_clob,',
'            p_template_id   => l_id );',
'',
'',
'',
' /* Some processing producing BLOB data and populating my_blob_data */',
'DBMS_CLOUD.PUT_OBJECT(',
'     credential_name => ''OCI$RESOURCE_PRINCIPAL'',',
'     object_uri => ''https://natdcshjumpstartprod.objectstorage.us-ashburn-1.oci.customer-oci.com/n/natdcshjumpstartprod/b/doc_gen/o/out%2Ftest.pdf'',',
'     contents => l_pdf); ',
'',
'',
'    apex_print.remove_template( p_template_id => l_id );',
'',
'',
'    apex_http.download(',
'        p_blob          => l_pdf,',
'        p_content_type  => ''application/pdf'',',
'        p_filename      => ''hello.pdf'' );',
'',
'    apex_application.stop_apex_engine;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>12010031410513424
);
end;
